<section class="section" id="github">
    <div class="container"><div class="section-head">
        <div class="eyebrow">GitHub</div>
        <h2>A live window into the<br>code behind the work.</h2>
        <p>Enter a GitHub username to load live public activity.</p>
    </div><div class="github-dashboard" id="githubDashboard"
    ><div class="github-header"><div class="github-header-left">
        <div class="github-icon">⌘</div>
        <h3>GitHub Activity</h3><div class="gh-status" id="ghStatus" aria-live="polite">
            <span class="dot"></span><span id="ghStatusText">READY</span></div>
        </div><a href="#" id="ghProfileLink" target="_blank" rel="noopener" hidden>View GitHub Profile ↗</a></div><div class="github-controls"><div class="input-wrap"><span class="prefix">github.com/</span><label class="sr-only" for="ghUsernameInput">GitHub username</label><input type="text" id="ghUsernameInput" placeholder="username" autocomplete="off"></div><button class="btn-load" id="ghLoadBtn" type="button"><span class="spinner"></span><span class="btn-label">Load</span></button></div><div id="ghContent" aria-live="polite"><div class="github-empty"><span class="empty-icon">⌘</span><h4>No data loaded yet</h4><p>Enter a GitHub username above to see public repositories and activity.</p><button type="button" class="empty-cta" id="ghTryExample">Try: mharmainfarooq1809-developer</button></div></div></div></div></section>
<style>
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.gh-profile-link,#ghProfileLink{font:13px var(--font-mono);color:var(--accent);border:1px solid var(--border);padding:8px 16px;border-radius:999px}.gh-status.is-fetching .dot{background:var(--accent);animation:pulse-dot 1.2s infinite}.gh-status.is-live .dot{background:var(--accent)}.gh-status.is-unavailable .dot{background:var(--danger)}.gh-profile,.gh-featured,.gh-repo-list{padding:28px 32px;border-bottom:1px solid var(--border)}.gh-profile-top,.gh-stat-row,.gh-repo-row,.gh-repo-row-right{display:flex;align-items:center}.gh-profile-top{gap:16px;margin-bottom:16px}.gh-avatar{width:48px;height:48px;border-radius:50%;border:1px solid var(--border)}.gh-handle,.gh-repo-name{font-family:var(--font-head);color:var(--text)}.gh-name,.gh-bio,.gh-repo-desc,.gh-list-heading{color:var(--muted-2)}.gh-bio{margin-bottom:16px}.gh-stat-row{gap:30px;flex-wrap:wrap}.stat-value{display:block;font:22px var(--font-mono);color:var(--accent)}.stat-label,.gh-list-heading{font:11px var(--font-mono);text-transform:uppercase}.gh-featured-label{font:11px var(--font-mono);color:var(--accent);margin-bottom:12px}.gh-featured-name{font:22px var(--font-head);margin-bottom:8px}.gh-repo-row{justify-content:space-between;gap:16px;padding:16px 0;border-top:1px solid var(--border)}.gh-repo-row-right{gap:16px;font:12px var(--font-mono);color:var(--muted-2)}.gh-repo-lang-dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px}.gh-view-all{display:block;padding:20px;text-align:center;color:var(--muted);font:13px var(--font-mono)}.github-error{padding:32px;text-align:center;color:var(--danger)}.empty-cta{margin-top:20px;background:none;cursor:pointer}@media(max-width:640px){.gh-profile,.gh-featured,.gh-repo-list{padding:20px}.gh-repo-row{align-items:flex-start;flex-direction:column}.github-header{flex-wrap:wrap}}
</style>
<script>
(() => { const input=document.getElementById('ghUsernameInput'), button=document.getElementById('ghLoadBtn'), content=document.getElementById('ghContent'), status=document.getElementById('ghStatus'), statusText=document.getElementById('ghStatusText'), profile=document.getElementById('ghProfileLink'); let loading=false; const setStatus=(state,text)=>{status.className='gh-status'+(state?' is-'+state:'');statusText.textContent=text}; const el=(tag,className,text)=>{const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node}; const addText=(parent,tag,className,text)=>parent.append(el(tag,className,text)); function clear(){content.replaceChildren()} function addRepo(repo, featured=false){const wrap=el('div',featured?'gh-featured':'gh-repo-row'), link=el('a',featured?'gh-repo-link':'gh-repo-name',repo.name);link.href=repo.html_url||'#';link.target='_blank';link.rel='noopener';if(featured){addText(wrap,'div','gh-featured-label','LATEST / FEATURED');const title=el('div','gh-featured-name');title.append(link);wrap.append(title);if(repo.description)addText(wrap,'p','gh-bio',repo.description);const meta=el('div','gh-repo-row-right');if(repo.language)meta.append(el('span','',repo.language));meta.append(el('span','',`★ ${repo.stargazers_count}`),el('span','',`⑂ ${repo.forks_count}`));wrap.append(meta)}else{const left=el('div','');left.append(link);if(repo.description)addText(left,'div','gh-repo-desc',repo.description);wrap.append(left);const right=el('div','gh-repo-row-right');if(repo.language)right.append(el('span','',repo.language));right.append(el('span','',`★ ${repo.stargazers_count}`));wrap.append(right)}return wrap} function render(data){clear();const p=data.profile, summary=el('div','gh-profile'), top=el('div','gh-profile-top');if(p.avatar_url){const image=el('img','gh-avatar');image.src=p.avatar_url;image.alt='';top.append(image)}const identity=el('div','');addText(identity,'div','gh-handle','@'+p.login);if(p.name)addText(identity,'div','gh-name',p.name);top.append(identity);summary.append(top);if(p.bio)addText(summary,'p','gh-bio',p.bio);const stats=el('div','gh-stat-row');[['Public repos',p.public_repos],['Followers',p.followers],['Following',p.following],['Languages',data.language_count]].forEach(([label,value])=>{const stat=el('div','');addText(stat,'span','stat-value',value);addText(stat,'span','stat-label',label);stats.append(stat)});summary.append(stats);content.append(summary);if(data.repos.length)content.append(addRepo(data.repos[0],true));if(data.repos.length>1){const list=el('div','gh-repo-list');addText(list,'div','gh-list-heading','More repositories');data.repos.slice(1).forEach(repo=>list.append(addRepo(repo)));content.append(list)}if(data.has_more){const all=el('a','gh-view-all','View all repositories on GitHub ↗');all.href=p.html_url;all.target='_blank';all.rel='noopener';content.append(all)}} async function load(value){const username=String(value||'').trim();if(!username||loading)return;loading=true;button.disabled=true;button.classList.add('loading');setStatus('fetching','FETCHING');clear();addText(content,'div','github-empty','Fetching public GitHub data…');try{const response=await fetch('api/github.php?username='+encodeURIComponent(username));const data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'GitHub data is temporarily unavailable.');profile.href=data.profile.html_url;profile.hidden=false;render(data);setStatus('live','LIVE')}catch(error){clear();const box=el('div','github-error');addText(box,'p','',error.message);content.append(box);profile.hidden=true;setStatus('unavailable','UNAVAILABLE')}finally{loading=false;button.disabled=false;button.classList.remove('loading')}} button.addEventListener('click',()=>load(input.value));input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();load(input.value)}});document.getElementById('ghTryExample')?.addEventListener('click',()=>{input.value='muhammadharmain';load(input.value)});setStatus('','READY'); })();
</script>
